import { verifyAdmin } from '../lib/auth';
import { forbidden } from 'next/navigation';
import Link from 'next/link';

export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin();

  if (!isAdmin) {
    forbidden();
  }

  return (
    <main style={{ padding: '2rem', fontFamily: 'sans-serif' }}>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session?.name} (Admin).</p>
      <div style={{ marginTop: '1rem', padding: '1rem', backgroundColor: '#f0f9ff', border: '1px solid #bae6fd', borderRadius: '4px' }}>
        <p>This is a protected admin area.</p>
        <p>You have successfully authenticated as an administrator.</p>
      </div>
      <div style={{ marginTop: '2rem' }}>
        <Link href="/" style={{ color: '#0284c7', textDecoration: 'none' }}>&larr; Back to Home</Link>
      </div>
    </main>
  );
}
